import{_ as i,c as t,a2 as a,o}from"./chunks/framework.CO0qOYmW.js";const n=JSON.parse('{"title":"浏览器面试题","description":"","frontmatter":{"title":"浏览器面试题","category":"面试题","excerpt":"工厂比喻：浏览器是一座工厂，进程是工厂中的车间，线程是车间内的流水线（实际运作的最小单位）。 定义：一个正在运行的程序实例，是操作系统分配资源（内存、I/O 等）的基本单位。 特性： 拥有独立的内存空间和系统资源（如文件描述符）。 可包含一..."},"headers":[],"relativePath":"interview/10-Browser.md","filePath":"interview/10-Browser.md","lastUpdated":1773591891000}'),e={name:"interview/10-Browser.md"};function c(s,l,r,u,d,p){return o(),t("div",null,l[0]||(l[0]=[a('<h1 id="浏览器面试题" tabindex="-1">浏览器面试题 <a class="header-anchor" href="#浏览器面试题" aria-label="Permalink to &quot;浏览器面试题&quot;">​</a></h1><h2 id="_1、线程与进程" tabindex="-1">1、线程与进程 <a class="header-anchor" href="#_1、线程与进程" aria-label="Permalink to &quot;1、线程与进程&quot;">​</a></h2><div class="info custom-block github-alert"><p class="custom-block-title">INFO</p><p><strong>工厂比喻</strong>：浏览器是一座工厂，进程是工厂中的车间，线程是车间内的流水线（实际运作的最小单位）。</p></div><div class="tip custom-block"><p class="custom-block-title">进程</p><ul><li><strong>定义</strong>：一个正在运行的程序实例，是操作系统分配资源（内存、I/O 等）的基本单位。</li><li><strong>特性</strong>： <ul><li>拥有独立的内存空间和系统资源（如文件描述符）。</li><li>可包含一个或多个线程。</li></ul></li></ul></div><div class="tip custom-block"><p class="custom-block-title">线程</p><ul><li><strong>定义</strong>：进程内的执行单元，是操作系统调度的最小单位。</li><li><strong>特性</strong>： <ul><li>同一进程的线程共享进程资源（如内存地址空间）。</li><li>每个线程拥有独立的执行流，支持并发执行。</li></ul></li></ul></div><h2 id="_2、浏览器有哪些进程和线程" tabindex="-1">2、浏览器有哪些进程和线程？ <a class="header-anchor" href="#_2、浏览器有哪些进程和线程" aria-label="Permalink to &quot;2、浏览器有哪些进程和线程？&quot;">​</a></h2><div class="tip custom-block github-alert"><p class="custom-block-title">浏览器进程模型</p><p></p><ul><li><code>浏览器主进程</code>（Browser）：负责浏览器的界面显示、用户交互、子进程的管理等。</li><li><code>网络进程</code>（Network）：负责加载网络资源。</li><li><code>渲染进程</code>（Renderer）：负责页面的渲染，解析 HTML、CSS、JavaScript，并绘制页面。</li><li><code>插件进程</code>（Plug-in）：负责插件的运行，例如 Flash。</li></ul></div><h2 id="_3、浏览器渲染原理" tabindex="-1">3、浏览器渲染原理 <a class="header-anchor" href="#_3、浏览器渲染原理" aria-label="Permalink to &quot;3、浏览器渲染原理&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">注意</p><ul><li>是指浏览器将 HTML、CSS、JavaScript 代码转换为可视化页面的过程。</li><li>渲染原理可以分为以下步骤：</li></ul><ol><li>解析 HTML 代码：浏览器将 HTML 代码解析为 DOM 树。</li><li>解析 CSS 代码：浏览器将 CSS 代码解析为 CSSOM 树。</li><li>合并 DOM 树和 CSSOM 树：将 DOM 树和 CSSOM 树合并为渲染树。</li><li>布局：计算渲染树中各元素的位置。</li><li>绘制：将渲染树绘制成页面。</li><li>合成：将页面的各层合成到一起。</li></ol></div><h2 id="_4、渲染进程" tabindex="-1">4、渲染进程 <a class="header-anchor" href="#_4、渲染进程" aria-label="Permalink to &quot;4、渲染进程&quot;">​</a></h2><div class="important custom-block github-alert"><p class="custom-block-title">作用</p><p></p><ul><li>渲染进程的主要工作是将 HTML、CSS、JavaScript 转换为用户可以看到和操作的视觉效果。</li><li>渲染进程的内部包含多个线程，例如 GUI、JavaScript 引擎、布局和绘制线程等。</li><li>主线程负责处理用户交互事件、子线程的管理和渲染。</li></ul></div><div class="tip custom-block github-alert"><p class="custom-block-title">渲染进程的任务包括但不限于：</p><p></p><ol><li>解析 HTML。</li><li>解析 CSS。</li><li>计算样式。</li><li>布局。</li><li>处理图层。</li><li>每秒把页面画 60 次。</li><li>执行全局 JS 代码。</li><li>执行事件处理函数。</li><li>执行计时器的回调函数。</li></ol></div><div class="tip custom-block github-alert"><p class="custom-block-title">渲染进程调度策略</p><p></p><ol><li>在最开始的时候，渲染主线程会进入一个无限循环</li><li>每一次循环会检查消息队列中是否有任务存在。如果有，就取出第一个任务执行，执行完一个后进入下一次循环；如果没有，则进入休眠状态。</li><li>其他所有线程（包括其他进程的线程）可以随时向消息队列添加任务。新任务会加到消息队列的末尾。在添加新任务时，如果主线程是休眠状态，则会将其唤醒以继续循环拿取任务。</li><li>如此，就可以让每个任务有条不紊的、持续的进行下去了。</li><li>整个过程，被称之为<code>事件循环（消息循环)</code></li></ol></div><h2 id="_5、何为事件循环" tabindex="-1">5、何为事件循环 <a class="header-anchor" href="#_5、何为事件循环" aria-label="Permalink to &quot;5、何为事件循环&quot;">​</a></h2><div class="tip custom-block github-alert"><p class="custom-block-title">概念</p><p></p><ul><li>事件循环是渲染进程的核心(工作方式)。</li><li>它是一种循环（不会结束的 for 循环），不断检查是否有异步任务需要执行，如果有，就将对应的回调函数推入执行栈。</li><li>主线程运行时，如果遇到需要执行的异步任务，就将该任务的回调函数添加到任务队列中。</li><li>当渲染进程空闲时，它会从任务队列中取出一个任务，并放入执行栈中执行。</li><li>如此循环，直到执行栈为空，渲染进程才会休眠，等待下一个任务的到来。</li></ul></div><h2 id="_6、浏览器的队列" tabindex="-1">6、浏览器的队列 <a class="header-anchor" href="#_6、浏览器的队列" aria-label="Permalink to &quot;6、浏览器的队列&quot;">​</a></h2><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p></p><ul><li>微队列：用户存放需要最快执行的任务，优先级「最高」 ,<code>Promise</code>、<code>MutationObserver</code></li><li>交互队列：用于存放用户操作后产生的事件处理任务，优先级「高」</li><li>延时队列：用于存放计时器到达后的回调任务，优先级「中」</li><li>其他队列：其他类型的任务，优先级「低」</li></ul></div><h2 id="_7、何为异步" tabindex="-1">7、何为异步 <a class="header-anchor" href="#_7、何为异步" aria-label="Permalink to &quot;7、何为异步&quot;">​</a></h2><div class="tip custom-block github-alert"><p class="custom-block-title">概念</p><p></p><ol><li><code>异步</code>是指，代码在执行过程中，一旦遇到一些无法立即处理(需要等待)的任务，就先将该任务的回调函数（即任务的执行结果）存放到消息队列中，然后继续执行后续代码，等到资源返回结果后，再将结果传递给对应的回调函数执行。</li></ol><ul><li>计时完成后需要执行的任务 —— <code>setTimeout</code>、<code>setInterval</code></li><li>网络通信完成后需要执行的任务 -- <code>XHR</code>、<code>Fetch</code></li><li>用户操作后需要执行的任务 -- <code>addEventListener</code></li><li>如果让渲染主线程等待这些任务的时机达到，就会导致主线程长期处于「阻塞」的状态，从而导致浏览器「卡死」。</li><li>为了解决这个问题，引入了事件循环机制，将这些异步任务的执行结果存放到消息队列中，主线程再从消息队列中取出执行。</li></ul></div><h3 id="_7-1、如何理解异步" tabindex="-1">7.1、如何理解异步 <a class="header-anchor" href="#_7-1、如何理解异步" aria-label="Permalink to &quot;7.1、如何理解异步&quot;">​</a></h3><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p></p><ol><li>JS是一门单线程的语言，这是因为它运行在浏览器的渲染主线程中，而渲染主线程只有一个。</li><li>而渲染主线程承担着诸多的工作，渲染页面、执行 JS 都在其中运行。</li><li>如果使用同步的方式，就极有可能导致主线程产生阻塞，从而导致消息队列中的很多其他任务无法得到执行。</li><li>这样一来，一方面会导致繁忙的主线程白白的消耗时间，另一方面导致页面无法及时更新，给用户造成卡死现象。</li><li>所以浏览器采用异步的方式来避免。具体做法是当某些任务发生时，比如计时器、网络、事件监听，主线程将任务交给其他线程去处理，自身立即结束任务的执行，转而执行后续代码。</li><li>当其他线程完成时，将事先传递的回调函数包装成任务，加入到消息队列的末尾排队，等待主线程调度执行。在这种异步模式下，浏览器永不阻塞，从而最大限度的保证了单线程的流畅运行。</li></ol></div><h3 id="_7-2、异步的实现" tabindex="-1">7.2、异步的实现 <a class="header-anchor" href="#_7-2、异步的实现" aria-label="Permalink to &quot;7.2、异步的实现&quot;">​</a></h3><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p></p><ul><li>异步的实现主要是通过回调函数实现的。</li><li>回调函数就是将任务的执行结果作为参数传入到函数中，待任务执行完毕后，再执行回调函数。</li><li>回调函数的优点是简单、灵活，缺点是不利于代码的阅读和维护。</li><li>为了解决这个问题，引入了 Promise 和 Generator。</li></ul></div><h2 id="_8、垃圾回收机制" tabindex="-1">8、垃圾回收机制 <a class="header-anchor" href="#_8、垃圾回收机制" aria-label="Permalink to &quot;8、垃圾回收机制&quot;">​</a></h2><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p></p><ul><li>当程序运行过程中，会不断的分配和回收内存，当一个变量不再被使用时，就将其回收。</li><li>目的：就是 <strong>为了减少内存的占用，提高程序的运行效率。</strong></li><li>三种实现方式： 标记清除、引用计数、分代收集</li></ul></div><h3 id="_8-1、标记清除" tabindex="-1">8.1、标记清除 <a class="header-anchor" href="#_8-1、标记清除" aria-label="Permalink to &quot;8.1、标记清除&quot;">​</a></h3><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p></p><ul><li>标记清除的基本思想是：从根集合开始，标记所有可达对象，然后清除没有标记的对象。</li><li>具体步骤： <ol><li>根集合：程序运行开始时，所有变量都是根集合。</li><li>标记过程：从根集合开始，递归遍历所有变量，标记所有可达对象。</li><li>清除过程：清除掉没有标记的对象。</li></ol></li><li>缺点： <ul><li>效率低：标记清除算法需要扫描整个堆内存，效率低。</li></ul></li></ul></div><h3 id="_8-2、引用计数" tabindex="-1">8.2、引用计数 <a class="header-anchor" href="#_8-2、引用计数" aria-label="Permalink to &quot;8.2、引用计数&quot;">​</a></h3><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p></p><ul><li>引用计数的基本思想是：每个对象都有一个引用计数属性，记录指向该对象的引用数量。</li><li>具体步骤： <ol><li>根集合：程序运行开始时，所有变量都是根集合。</li><li>标记过程：从根集合开始，递归遍历所有变量，将所有引用计数为 0 的对象标记为垃圾。</li><li>清除过程：清除掉所有标记的对象。</li></ol></li><li>缺点： <ul><li>循环引用：当两个对象互相引用时，引用计数无法解决循环引用的问题。</li></ul></li></ul></div><h3 id="_8-3、分代收集" tabindex="-1">8.3、分代收集 <a class="header-anchor" href="#_8-3、分代收集" aria-label="Permalink to &quot;8.3、分代收集&quot;">​</a></h3><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p></p><ul><li>它将内存分为不同的代，不同代的对象采用不同的垃圾回收算法。</li><li>具体步骤： <ol><li>新生代：新创建的对象都放在新生代。</li><li>老生代：经历过一次垃圾回收的对象，放入老生代。</li><li>整理过程：将新生代的对象复制到老生代，并进行整理。</li></ol></li><li>优点： <ul><li>解决了内存碎片问题。</li><li>降低了内存分配时的开销。</li></ul></li><li>缺点： <ul><li>代的划分不好，就容易产生内存碎片。</li><li>代的划分容易产生内存浪费。</li></ul></li></ul></div><h2 id="_9、i-o-密集型任务与-cpu-密集型任务" tabindex="-1">9、I/O 密集型任务与 CPU 密集型任务 <a class="header-anchor" href="#_9、i-o-密集型任务与-cpu-密集型任务" aria-label="Permalink to &quot;9、I/O 密集型任务与 CPU 密集型任务&quot;">​</a></h2><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p></p><ul><li>I/O 密集型任务：指的是需要大量的输入输出操作，比如读取文件、发送网络请求、数据库查询等。</li><li>CPU 密集型任务：指的是需要大量的计算操作，比如复杂的算法、数学计算等。</li></ul></div>',33)]))}const b=i(e,[["render",c]]);export{n as __pageData,b as default};
